<?php namespace App\Http\Controllers\Api\V1; use Illuminate\Http\Request; use App\Models\{Exam,ExamSubject,ExamMark}; class ExamController extends Controller {public function index(Request $r){return $this->ok(Exam::where('school_id',$r->user()->school_id)->paginate(50));}public function store(Request $r){$this->authorizeRole($r,['super_admin','admin']);$d=$r->validate(['name'=>'required|string','start_date'=>'nullable|date','end_date'=>'nullable|date']);$d['school_id']=$r->user()->school_id;return $this->ok(Exam::create($d),'Exam created',201);}public function update(Request $r,$id){$this->authorizeRole($r,['super_admin','admin']);$x=Exam::where('school_id',$r->user()->school_id)->findOrFail($id);$x->update($r->all());return $this->ok($x,'Exam updated');}public function destroy(Request $r,$id){$this->authorizeRole($r,['super_admin','admin']);Exam::where('school_id',$r->user()->school_id)->findOrFail($id)->delete();return $this->ok(null,'Exam deleted');}public function dateSheet(Request $r,$id){$this->authorizeRole($r,['super_admin','admin']);$e=Exam::where('school_id',$r->user()->school_id)->findOrFail($id);$d=$r->validate(['subjects'=>'required|array']);foreach($d['subjects'] as $x)ExamSubject::updateOrCreate(['school_id'=>$e->school_id,'exam_id'=>$e->id,'subject_id'=>$x['subject_id']],['exam_date'=>$x['exam_date'],'start_time'=>$x['start_time']??null,'end_time'=>$x['end_time']??null]);return $this->ok($e->load('subjects'),'Date sheet saved');}public function marks(Request $r,$id){$this->authorizeRole($r,['super_admin','admin','teacher']);$e=Exam::where('school_id',$r->user()->school_id)->findOrFail($id);$d=$r->validate(['marks'=>'required|array']);foreach($d['marks'] as $x)ExamMark::updateOrCreate(['school_id'=>$e->school_id,'exam_id'=>$e->id,'student_id'=>$x['student_id'],'subject_id'=>$x['subject_id']],['marks'=>$x['marks'],'total_marks'=>$x['total_marks']??100,'submitted_by'=>$r->user()->id]);return $this->ok(null,'Marks saved');}public function reportCard(Request $r,$id,$student_id){$e=Exam::where('school_id',$r->user()->school_id)->findOrFail($id);$m=ExamMark::where('school_id',$e->school_id)->where('exam_id',$id)->where('student_id',$student_id)->get();$total=$m->sum('total_marks');$obt=$m->sum('marks');return $this->ok(['exam'=>$e,'student_id'=>(int)$student_id,'marks'=>$m,'total_marks'=>$total,'obtained_marks'=>$obt,'percentage'=>$total?round($obt/$total*100,2):0]);}}
